{nameGoroskop.map((el, i) =>{
return <div className="name" key={i+1}>{el}</div>;
})}
</div>
 <div className="right">
 {dateGoroskop.map((el, i) =>{
   return <div className="date"key={i+2}>{el}</div>;
 })}
 </div>
 </div>

  )} 
